-- Korean copy edit of the forthcoming dating questions and their three sample replies.
-- The schedule and identities are unchanged. Do not modify a prompt a member has answered.
set local lock_timeout = '5s';
lock table pajang_private.answers in share row exclusive mode;
lock table pajang_private.personality_question_catalog in share row exclusive mode;

do $copy_edit$
declare
  item record;
  previous pajang_private.personality_question_catalog;
begin
  for item in
    select * from jsonb_to_recordset($reviewed$[
      {"id":40002,"before":"2286c2fec3da5f313f7d7e64bc73dd35","prompt":"썸 탈 때 스킨십은 어디까지 괜찮아요?","samples":["사귀기 전엔 손잡는 것도 조금 이른 것 같아요.","손잡고 안아 주는 정도면 설레고 좋아요.","서로 마음이 통하면 사귀기 전에 키스해도 좋아요."]},
      {"id":40003,"before":"8424b3152a5b6176f6f3d282ce6633dd","prompt":"썸 타는 사람이 내 앞에서 다른 사람한테 “번호 좀 알려 주실래요?” 하고 물어요. 둘만 남으면 뭐라고 할 것 같아요?","samples":["“나만 데이트라고 생각했어?” 하고 물어볼래요.","아직 사귀는 사이도 아니라서 그날은 아무 말 안 할 것 같아요.","“솔직히 나 좀 질투 났어” 하고 제 마음부터 말할래요."]},
      {"id":40004,"before":"1e9154bcc76ec6142c2c9eeae84ff8ec","prompt":"세 번이나 데이트했는데 친구들 앞에선 나를 ‘아는 사람’이라고 소개해요. 뭐라고 소개해 주면 좋았을까요?","samples":["아직 우리 사이를 뭐라고 하긴 어색해서 그냥 제 이름만 말해 줘도 좋아요.","“요즘 제일 자주 만나는 사람”이면 기분 좋았을 것 같아요.","둘이 사귀는 건지부터 얘기하고, 그다음엔 당당하게 애인이라고 소개해 주면 좋겠어요."]},
      {"id":40005,"before":"c9d1c631dadc6197ef14aeb3e80fc4f1","prompt":"한동안 연락이 없던 썸 상대가 새벽 한 시에 “자?” 하고 문자를 보냈어요. 뭐라고 답할 것 같아요?","samples":["“아직 안 자. 이 시간에 웬일이야?” 하고 바로 답해요.","아침에 “잤어. 무슨 일 있었어?”라고 보내요.","“반갑긴 한데 다음엔 낮에도 연락해 줘”라고 말할래요."]},
      {"id":40007,"before":"4c5f05118de6196edae373323b321cb4","prompt":"나한테는 다정한 사람이 식당 직원한테는 무뚝뚝해요. 어떤 행동을 보면 호감이 식을 것 같아요?","samples":["말수가 적은 건 괜찮지만 실수했다고 면박 주면 바로 식어요.","직원이 잘 챙겨 줬는데도 고맙다는 말 한마디 없이 나가면 좀 깨요.","한 번 본 걸로 판단하진 않고 다른 날에도 그런지 봐요."]},
      {"id":40008,"before":"a4da0d5b4b77531f6ae8c0710c15c4b2","prompt":"썸 타는 사람이 단둘이 여행을 가자고 해요. 숙소를 잡기 전에 어떤 얘기를 나누고 싶나요?","samples":["“난 방을 따로 쓰면 더 편할 것 같아.”","“같은 방도 좋은데, 넌 어느 쪽이 편해?”","“여행 가기 전에 우리 사이부터 얘기하고 싶어.”"]},
      {"id":40009,"before":"f4b2bbb131a6d8a916cb1df57e551b80","prompt":"좋아하는 사람이 “나 좋아하지?” 하고 웃으면서 물어요. 내 입에서 나올 첫마디는 뭔가요?","samples":["“응. 티 많이 났어?”","“왜, 너도 나 좋아해?”","“장난이면 대답 안 할래. 진짜 궁금한 거야?”"]},
      {"id":40010,"before":"7b50cab697ce341e4d34051174f6aed6","prompt":"연인이 내 휴대폰 비밀번호를 궁금해해요. 서로의 휴대폰은 어디까지 봐도 괜찮다고 생각해요?","samples":["잠금 풀어서 같이 들을 노래 고르는 정도는 괜찮아요.","비밀번호는 서로 몰라도 된다고 생각해요.","서로 알아도 괜찮지만 대화창을 열 땐 꼭 물어봤으면 해요."]},
      {"id":40011,"before":"c4393520fcd686afebebdf81dcfba135","prompt":"얘기는 잘 통하는데 손을 잡아도 설레지 않아요. 한 번 더 만나자고 하면 어떻게 할 것 같아요?","samples":["첫날이라 긴장했을 수도 있으니까 한 번 더 만나 볼래요.","다음 약속을 잡기 전에 “난 친구처럼 느껴져”라고 말할래요.","이번엔 편하게 놀면서도 설레는 순간이 있는지 보고 싶어요."]},
      {"id":40012,"before":"66c7415c9160e4c16a964277bc868336","prompt":"첫 데이트가 끝나고 상대가 커피값까지 딱 반으로 나눠서 보내 달래요. 어떤 기분이 들 것 같아요?","samples":["오히려 마음이 편해요. 각자 얼마 낼지 눈치 볼 필요가 없잖아요.","돈보다 예고 없이 정산 알림부터 온 게 서운해요.","반씩 내는 건 괜찮아요. 다음엔 한 명이 밥 사고 한 명이 커피 사면 더 편할 것 같아요."]},
      {"id":40013,"before":"df425e77bc263a049a54a9688e02e765","prompt":"연인이 친구들 앞에서 우리 둘만 아는 애칭으로 나를 놀려요. 나는 그 자리에서 어떻게 하나요?","samples":["같이 웃으면서 저도 연인의 애칭을 불러요.","눈을 맞추고 “그건 우리끼리만”이라고 짧게 말해요.","그 자리에선 넘기고 둘이 있을 때 왜 민망했는지 말해요."]},
      {"id":40014,"before":"d10daf3c5b5d592c6d3128021f87c54f","prompt":"첫 데이트가 끝날 무렵 상대가 “키스해도 돼?” 하고 물어요. 나라면 뭐라고 답할까요?","samples":["저도 하고 싶었다면 웃으면서 “응, 나도”라고 해요.","“오늘은 안아 주는 것까지만”이라고 말해요.","아직은 어색해서 “난 좀 더 친해진 다음이 좋아”라고 해요."]},
      {"id":40015,"before":"e69e19fc00a2f71ed0a3efdc453519bc","prompt":"연인이 오랜 친구와 단둘이 술을 마시고 새벽에 들어왔어요. 뭐가 제일 신경 쓰이나요?","samples":["늦는다고 연락은 해 줬는지가 제일 신경 쓰여요.","그 친구에게 우리 연애 고민까지 털어놨을까 궁금해요.","약속만 지켰다면 늦게 들어왔다는 건 별로 신경 안 써요."]},
      {"id":40016,"before":"0b72da8b554076296cc09ee391e845e3","prompt":"썸 타는 사람이 “굳이 사귄다고 해야 해? 난 지금처럼 지내고 싶어”라고 해요. 계속 만나려면 뭐부터 얘기해 보고 싶어요?","samples":["다른 사람도 만날 수 있는 사이인지 알고 싶어요.","지금 서로 좋아한다는 말만 들으면 당장은 충분해요.","“나는 연인으로 만나고 싶은데, 너는 어때?”라고 물어볼래요."]},
      {"id":40017,"before":"49d434aa55645e5f4eff375564e346a4","prompt":"내 메시지엔 답이 없는데 상대가 SNS에 새 사진을 올렸어요. 그걸 보면 어떻게 할 것 같아요?","samples":["사진이 재밌으면 거기에 그냥 하트를 눌러요.","대화할 기운과 사진 올릴 기운은 다르니까 제 할 일을 해요.","이런 일이 자주 있으면 “내 답장은 맨날 뒷순서 같아서 좀 서운해”라고 말해요."]},
      {"id":40018,"before":"9af49c32345b0dc4efceef81381d972c","prompt":"요즘 썸 타는 사람이 있는데, 전 애인이 내가 좋아하던 빵을 사 들고 집 근처에 왔대요. 뭐라고 답할까요?","samples":["“마음은 고마운데 지금은 만나지 않을게.”","“잠깐 나갈게. 무슨 얘길 하고 싶었어?”","“갑자기 찾아오면 곤란해. 다음엔 먼저 물어봐 줘.”"]},
      {"id":40019,"before":"7927f2b8b77c6b1c7e549d35119aaa7a","prompt":"외모는 내 이상형이 아닌데 얘기를 나눌수록 또 보고 싶어요. 언제 ‘아, 나 이 사람 좋아하네’ 싶을까요?","samples":["재밌는 일이 생기면 그 사람한테 제일 먼저 말하고 싶을 때요.","다른 사람과 소개팅한다는 말에 마음이 철렁할 때요.","나란히 걷다가 저도 모르게 손을 잡고 싶어질 때요."]},
      {"id":40020,"before":"1ce69d5d2b749471c763bae9d7e24dc0","prompt":"유난히 보고 싶은 날인데 연인은 “오늘은 혼자 있고 싶어”라고 해요. 뭐라고 답할까요?","samples":["“푹 쉬어. 내일 만나면 오래 안아 줘.”","“오늘 좀 힘들었어. 통화 딱 5분은 어때?”","“나도 오늘은 내 친구 만나고 올게” 하고 각자 시간을 보내요."]},
      {"id":40021,"before":"6b4bef9659e254ccfadcadda141c0a51","prompt":"오래 친구로 지낸 사람에게 마음을 살짝 내비친다면 뭐라고 말하고 싶어요?","samples":["“다른 사람이랑 데이트한 얘기, 요즘은 듣기가 좀 어렵더라.”","“우리 이번엔 둘이서 데이트할래?”","“오늘 집 가기 아쉽다는 말, 나 너한테만 해.”"]},
      {"id":40022,"before":"c8ec9c7edabf6a53b04593bfb01f79d3","prompt":"연인이 친한 친구에게 우리가 싸운 얘기를 했어요. 어떤 얘기만큼은 둘 사이에 남겨 두고 싶나요?","samples":["둘만 아는 제 가족 사정은 빼고 얘기해 줬으면 해요.","힘들었다고 말하는 건 좋지만 대화 캡처까지 보여 주면 싫어요.","조언을 받는 사이라면 사실대로 이야기해도 괜찮아요."]},
      {"id":40023,"before":"4e6fb20d60724585a6e1bc780b99c906","prompt":"좋아하는 사람한테 고백을 받았는데 몇 달 뒤면 멀리 이사를 간대요. 그 고백에 뭐라고 답하고 싶어요?","samples":["“나도 네가 좋아. 멀리 가기 전까지라도 만나 보고 싶어.”","“나도 마음이 있어. 이사 가면 얼마나 자주 볼 수 있을까?”","“나도 네가 좋은데 장거리는 자신이 없어. 조금만 생각해 봐도 돼?”"]},
      {"id":40024,"before":"060efb73744a6c88277c9b0db94477dd","prompt":"첫 여행을 계획하는데 연인이 생각한 예산과 내 예산이 두 배나 차이 나요. 어디서부터 맞춰 볼까요?","samples":["둘 다 무리 없이 낼 수 있는 가격대로 숙소부터 찾아봐요.","제가 꼭 하고 싶은 일이 비싸다면 그만큼은 제가 더 낼래요.","이번엔 가까운 곳에 가고 큰 여행은 같이 돈을 모아 가요."]},
      {"id":40025,"before":"6f935de27939b1ac30c2e81939b3857d","prompt":"싸운 뒤 연인이 사과 대신 내가 좋아하는 야식을 시켜 놨어요. 마주 앉으면 첫마디로 뭐라고 할까요?","samples":["“고마워. 근데 아까 한 말은 먼저 얘기하고 싶어.”","“일단 먹자. 나도 배고파서 더 예민했나 봐.”","“이거 나 기분 풀어 주려고 시킨 거야?” 하고 먼저 웃어 봐요."]},
      {"id":40026,"before":"fe835b94efc5418abb414aae4fd38ebb","prompt":"둘만 있을 땐 안아 주는 게 좋은데, 이번엔 사람이 많은 횡단보도에서 연인이 두 팔을 벌려요. 어떻게 반길까요?","samples":["저도 반가워서 그대로 폭 안겨요.","웃으면서 손만 잡고 조용한 곳에 가서 안아 줘요.","“여기선 쑥스러워” 하고 팔짱을 껴요."]},
      {"id":40027,"before":"967d218290fc3cea1451f103586f2ac6","prompt":"연인에게 좋은 일이 생겼는데 나보다 먼저 소식을 들은 사람이 있어요. 어떤 경우라면 서운할까요?","samples":["늘 그 사람한테 먼저 말한다는 걸 알게 되면 서운해요.","누가 먼저 알았든 연인이 직접 신나서 들려주면 좋아요.","정작 저는 다른 사람한테 전해 들었다면 서운할 것 같아요."]},
      {"id":40028,"before":"f49579e6f697c26286deb633e6b6ff20","prompt":"키스한 다음 날, 썸 상대가 아무 일 없었다는 듯 날씨 얘기만 해요. 이럴 때 뭐라고 말하고 싶어요?","samples":["“어제 일, 난 좋았어. 넌 어땠어?”","“오늘도 볼래?” 하고 직접 만나서 표정을 보고 싶어요.","저도 일단 날씨 얘기할래요. 어제 일은 천천히 얘기하고 싶어요."]},
      {"id":40029,"before":"6b0af9b04fb34cf5cdad51b2b6292c30","prompt":"소개팅 다음 날 “재밌었어요”라는 답이 왔는데 다음 약속 얘기는 없어요. 나라면 뭐라고 보낼까요?","samples":["“저는 또 보고 싶은데, 금요일 저녁 어때요?”","“저도요!”까지만 보내고 이번엔 상대가 제안하길 기다려요.","어제 같이 얘기한 영화를 핑계로 대화를 조금 더 이어 가요."]},
      {"id":40030,"before":"4500406e40f5ab6e33793d63980c973c","prompt":"연인이 예전에 헤어진 이유를 들려줄 때 어떤 말이 가장 오래 마음에 남나요?","samples":["“나도 그때 이건 잘못했어” 하고 자기 얘기도 하는 게 기억에 남아요.","전 애인을 계속 깎아내리면 나중엔 내 얘기도 저렇게 할까 싶어요.","“그때는 피하기만 했는데 이젠 서운하면 얘기하려고 해” 같은 말이요."]},
      {"id":40031,"before":"dcdcc70e1459a683b0ef921f25f1e5fe","prompt":"모임이 끝나고 마음에 드는 사람과 단둘이 엘리베이터에 탔어요. 문이 열리기 전에 뭘 하고 싶나요?","samples":["“다음엔 우리 둘이 볼래요?” 하고 바로 물어요.","아까 둘만 웃었던 얘기를 다시 꺼내요.","눈 마주치고 인사만 해요. 연락은 나중에 보내는 게 더 편해요."]},
      {"id":40033,"before":"fd4b5dabfc51ab50d2a49132a67652ba","prompt":"퇴근하는데 연인이 꽃다발을 들고 회사 앞에서 기다리고 있어요. 가장 먼저 어떤 생각이 들어요?","samples":["‘내가 이 꽃 좋아하는 걸 기억했네’ 싶어서 웃음이 날 것 같아요.","동료들이 보고 있는지부터 살필 것 같아요.","바쁜데 일부러 제 퇴근 시간에 맞춰 온 게 고마워요."]},
      {"id":40034,"before":"07ac72be9f8dd8196e0a1e9fc217a8dc","prompt":"다툰 날 연인이 위치 공유 앱으로 내가 어디 있는지 몇 번이나 봤대요. 앞으로 위치는 어떻게 공유하고 싶나요?","samples":["귀갓길처럼 필요한 때만 잠깐 켜고 싶어요.","뭐가 그렇게 걱정됐는지 들어 보고 계속 켜 둘지 같이 정하고 싶어요.","어디 있냐고 직접 물어보는 게 편해서 공유는 끄고 싶어요."]},
      {"id":40035,"before":"377c7a0aafcf54f32d31b292c480599c","prompt":"다른 사람과 첫 데이트를 하기로 한 날, 내가 오래 짝사랑한 사람이 고백해요. 그 고백에 뭐라고 답할까요?","samples":["“나도 오래 좋아했어. 오늘 만나기로 한 사람한테 먼저 얘기할게.”","“지금 바로 답하긴 어려워. 조금만 생각해 봐도 될까?”","“좋아했던 건 맞는데 지금은 알아 가고 싶은 사람이 있어.”"]},
      {"id":40036,"before":"4663859c9a7bacf6a35c63eadba69753","prompt":"연인이 선물 가격을 듣고 “그 돈이면 우리 맛있는 거 먹지”라고 해요. 다음 기념일엔 어떻게 하고 싶나요?","samples":["이번엔 선물 대신 둘이 가 보고 싶던 식당을 예약해요.","비싼 선물은 안 해도 서로 작은 선물 하나씩은 골라 주고 싶어요.","기념일 전에 원하는 걸 각자 하나씩 말해 보고 싶어요."]},
      {"id":40038,"before":"060d60e499d3917fe52516d4c857050a","prompt":"썸 타는 사람과 나란히 걷는데 상대는 두 손을 주머니에 넣고 있어요. 손을 잡고 싶다면 어떻게 할까요?","samples":["“나 손잡고 걷는 거 좋아해. 너는 어때?”","오늘은 나란히 걷고, 헤어질 때 “다음엔 손잡고 걸을까?” 하고 물어요.","“나 지금 손잡고 싶은데 조금 떨린다” 하고 그냥 털어놔요."]},
      {"id":40039,"before":"4876b325a678737f5e31428834c0ff7c","prompt":"내 친한 친구가 연인이 말하던 이상형이랑 꼭 닮았어요. 셋이 만나면 뭐가 제일 신경 쓰일 것 같아요?","samples":["괜히 두 사람이 같은 농담에 웃는지 보게 될 것 같아요.","이상형이랑 실제로 좋아하는 사람은 다를 수 있어서 평소처럼 놀아요.","제가 괜히 둘 사이에 끼어든 것처럼 느껴질까 봐 그게 더 신경 쓰여요."]},
      {"id":40040,"before":"3ebd3535991f4e3a588c3de2116fe263","prompt":"썸 타는 사람이 아직 소개팅 앱을 쓰고 있어요. 언제쯤 그만 쓰길 바라나요?","samples":["둘이 다른 사람은 안 만나기로 얘기한 날부터요.","몇 번 만나고 서로 마음을 표현했다면 자연히 그만두길 바라요.","저는 딱 언제부터라고 정하진 않아요. 다른 사람도 만나고 있다면 솔직히 말해 주면 돼요."]},
      {"id":40041,"before":"2dd3cf9d3bd2f6d94ea9920ed3438f73","prompt":"만나면 다정한데 문자 답장은 늘 “ㅇㅇ”이에요. 가끔은 어떤 답장을 받고 싶어요?","samples":["“지금 일하는 중인데 이따 네 얘기 제대로 듣고 싶어.”","어제 제가 걱정했던 일을 기억하고 “오늘 그거 잘됐어?” 하고 물어봐 주면 좋아요.","전 짧은 답도 편해서 만났을 때 다정하면 충분해요."]},
      {"id":40042,"before":"5495ded29d93490cf9ce7bb38ed2dff8","prompt":"연인이 가자고 한 식당이 전 애인과 기념일마다 가던 곳이래요. 그 말을 듣고 뭐라고 할 것 같아요?","samples":["“그 집 뭐가 그렇게 맛있어? 나도 먹어 볼래.”","“오늘은 우리 둘 다 처음 가는 곳에 가 보면 어때?”","“오늘 거기 가고 싶은 이유가 있어?” 하고 먼저 물어볼래요."]},
      {"id":40043,"before":"44987c418db112e243a9d596bfb87a82","prompt":"첫 데이트에서 상대가 조금 서툴러서 오히려 마음이 가는 순간은 언제인가요?","samples":["칭찬을 연습해 온 티가 나서 둘 다 웃음이 터질 때요.","길을 잘못 들었는데 솔직히 인정하고 같이 지도를 보는 모습이요.","대화가 끊겨도 억지로 채우지 않고 수줍게 웃는 모습이요."]},
      {"id":40044,"before":"2376ca99e07c495389b3d5d3687842ad","prompt":"연인이 연락도 없이 집 앞에 찾아온다면 어떤 기분이 들 것 같아요?","samples":["몸이 안 좋다고 한 날 죽을 들고 왔다면 참 반가워요.","아무리 보고 싶어도 제 공간에 올 땐 먼저 연락해 줬으면 해요.","잠깐 얼굴만 보는 건 좋은데 자고 갈 생각으로 왔다면 부담스러워요."]},
      {"id":40045,"before":"404817cc91843fa74a7b52b92199b310","prompt":"연인이 처음으로 “사랑해”라고 했는데 나는 아직 그 말이 안 나와요. 어떻게 마음을 전할까요?","samples":["“나도 네가 정말 좋아. 그 말은 조금 더 있다가 하고 싶어.”","꼭 안아 주면서 “그렇게 말해 줘서 고마워”라고 해요.","“그 말 들으니까 너무 좋다”라고 지금 느끼는 것만 전해요."]},
      {"id":40046,"before":"3623acdf0565a0488e90f0a1969f280f","prompt":"연인이 SNS에 둘이 찍은 사진을 올렸는데 내 얼굴만 안 보이게 잘랐어요. 어떤 이유라면 이해할 수 있을까요?","samples":["제 허락 없이 얼굴을 올리기 조심스러웠다면 고마워요.","원래 다른 사람 얼굴도 안 올리는 편이라면 이해해요.","누군가에게 우리 사이를 숨기려는 거라면 이유부터 솔직하게 듣고 싶어요."]},
      {"id":40047,"before":"e51eb2900ac185894e9ecd008003e301","prompt":"친한 친구와 내가 같은 사람을 좋아한다는 걸 알았어요. 셋이 다시 만나기 전에 어떻게 하고 싶어요?","samples":["친구에게 “나도 마음 있어” 하고 먼저 털어놔요.","좋아하는 사람에게 제 마음을 전하고 그 사람 생각도 듣고 싶어요.","아직 가벼운 호감이라면 며칠 혼자 생각하고 싶어요."]},
      {"id":40048,"before":"e526ec2783310215abb7880e911e5f3e","prompt":"연인이 급한 일이 생겼다며 꽤 큰돈을 잠깐 빌려 달래요. 빌려줄지 어떻게 정할 것 같아요?","samples":["돌려받지 못해도 괜찮을 만큼만 빌려줘요.","사정과 갚을 날짜를 함께 얘기할 수 있어야 해요.","연인끼리는 돈을 빌려주지 않는다는 제 기준을 말해요."]},
      {"id":40049,"before":"9f1cbe823408211ffd91193ab9025809","prompt":"연인이 “미안한데, 너도 그랬잖아”라고 사과해요. 그 말을 듣고 대화를 어떻게 이어가나요?","samples":["“네가 서운했던 것도 들을게. 일단 지금 하던 얘기부터 마저 하자.”","제 행동이 떠오르면 그 부분은 바로 사과해요.","감정이 올라올 것 같아서 잠깐 산책하고 다시 얘기하자고 해요."]},
      {"id":40050,"before":"c2ef98b7388fe181c00966cb567fa20c","prompt":"연인이 “손도 늘 내가 먼저 잡잖아”라며 서운해해요. 나는 어떤 순간에 먼저 손을 잡거나 안아 주고 싶나요?","samples":["오랜만에 만났을 땐 반가워서 제가 먼저 꼭 안아 주고 싶어요.","둘만 있을 때는 쑥스럽지 않아서 제가 먼저 손을 잡아요.","제가 먼저 손잡기는 아직 쑥스러워요. 대신 둘이 영화 볼 땐 어깨에 살짝 기대요."]},
      {"id":40051,"before":"f704bd130b35ac0e72d41e75d0a4eba3","prompt":"다른 사람이 내가 보는 앞에서 내 연인에게 호감을 표현해요. 그때 연인이 뭐라고 해 주면 좋을까요?","samples":["“저 만나는 사람 있어요” 하고 짧게 알려 주면 돼요.","장난으로 넘기지 말고 관심 없다고 분명히 말해 줬으면 해요.","어떻게 거절할지는 맡기고 나중에 제 기분만 한 번 물어봐 주면 돼요."]},
      {"id":40052,"before":"00cf77c82a732d6abf91ffbd4eaca71b","prompt":"둘이 있으면 꼭 연인 같은데 데이트 신청은 늘 내 몫이에요. 다음번엔 어떻게 하고 싶나요?","samples":["이번엔 상대가 먼저 보자고 할 때까지 기다려 보고 싶어요.","이번 주는 약속을 비워 둘래요. 매번 제가 계획하려니 좀 지쳐요.","전 기다리기보다 “다음엔 네가 데이트 신청해 줘”라고 말할 것 같아요."]},
      {"id":40053,"before":"4b42bbb26d1daa862149e0f0ab89d838","prompt":"술자리에서 전화한 연인이 벌써 같은 얘기를 세 번째 해요. 이쯤 되면 뭐라고 할 것 같아요?","samples":["“집에 잘 들어가고, 도착하면 문자 하나 줘” 하고 끊고 싶어요.","귀여워서 한두 번은 듣다가 “그다음 얘기는 내일 해 줘” 하고 웃을 것 같아요.","취한 사람과 통화하는 게 힘들어서 “내일 맨정신에 얘기하자”라고 해요."]},
      {"id":40055,"before":"4e842d6dba3fca5d55a2d676d443d4c2","prompt":"데이트 때 어떤 칭찬을 들으면 집에 가는 길에도 자꾸 생각날까요?","samples":["“너 웃을 때 나도 따라서 웃게 돼.”","“아까 친구 얘기할 때 보니까 너 사람 참 잘 챙기더라.”","“너랑 있으면 나도 내 얘기를 더 하고 싶어져.”"]},
      {"id":40056,"before":"8ae77c15414fd21f356afaf5f9524223","prompt":"연인이 우리 집에 자기 칫솔을 하나 두고 가겠대요. 그 말을 들으면 어떤 생각이 들어요?","samples":["다음에 또 올 생각을 했다는 게 귀여워요.","제 집을 같이 쓰는 느낌이라 먼저 물어봐 주면 좋겠어요.","매번 들고 다니기 번거로웠겠다 싶어요. 크게 의미를 두진 않아요."]},
      {"id":40057,"before":"3f96a8d28861d069bfba20daea68479b","prompt":"내 생일에 친구들이 보는 앞에서 고백을 받았어요. 그 자리에서 어떻게 답하고 싶나요?","samples":["저도 좋아했다면 사람들 앞에서 좋다고 답하고 싶어요.","고맙다고 하고 제 대답은 따로 만나서 들려주고 싶어요.","갑자기 주목받으면 마음과 상관없이 일단 조용한 곳으로 가고 싶어요."]},
      {"id":40058,"before":"4bf6f8bc360f372791a6b0fe04026cb6","prompt":"썸 타는 사람이 친구한테 조언을 구하려고 우리 대화를 캡처해서 보여 줬대요. 둘이 나눈 얘기는 어디까지 전해도 괜찮아요?","samples":["제가 보낸 말 그대로 보여 줄 땐 먼저 물어봤으면 해요.","이름이나 개인 얘기를 가리고 데이트 신청 문구만 보여 주는 건 괜찮아요.","무슨 얘기를 했는지 대충 전하는 건 괜찮지만 제가 쓴 문장은 둘만 봤으면 해요."]},
      {"id":40059,"before":"d9cbd5c7e08d649553ebcce4d13bcaf9","prompt":"연인과 미래 얘기를 할 때, 어떤 문제에서 생각이 다르면 가장 고민될까요?","samples":["아이를 갖고 싶은지에 대해 생각이 다르면 오래 고민할 것 같아요.","계속 살고 싶은 나라가 다르면 누가 양보할지 막막해요.","한 사람은 곧 결혼하고 싶고 다른 사람은 몇 년 더 기다리고 싶다면 고민돼요."]},
      {"id":40060,"before":"9b6c1a70279947579884782d81a4402b","prompt":"금요일마다 데이트하는데 연인이 이번 달엔 금요일마다 취미 모임에 가고 싶대요. 둘이 만나는 날은 어떻게 정하고 싶어요?","samples":["요일은 괜찮으니 둘이 만날 다른 날부터 같이 정해요.","한 달에 한 번쯤은 원래 약속을 지켜 주면 좋겠어요.","이번 달은 취미를 즐기라고 하고 저도 빈 금요일에 하고 싶던 걸 할래요."]},
      {"id":40061,"before":"f5826aa3815441ad4282b39ee1121ee0","prompt":"내가 서운하다고 했더니 연인이 “장난이었잖아”라고 해요. 알아줬으면 하는 건 뭔가요?","samples":["장난인 줄 알아도 그 말에 상처받을 수 있다는 거예요.","다음부터 그 주제로는 안 놀리겠다는 한마디면 돼요.","“그 얘기는 나한테 좀 민감해”라는 제 말을 웃어넘기지 않았으면 해요."]},
      {"id":40062,"before":"ade17b805ebbbd2d57e2fe26e914eb7d","prompt":"소파에 나란히 앉은 썸 상대가 “조금 더 가까이 앉아도 돼?” 하고 물어요. 나라면 어떻게 답할까요?","samples":["옆자리를 톡톡 두드리면서 “응, 이리 와” 하고 반겨요.","“지금이 딱 좋아. 더 가까이 앉고 싶어지면 내가 먼저 갈게.”","“옆에 앉는 건 좋아. 어깨에 기대는 건 아직 좀 쑥스러워.”"]},
      {"id":40063,"before":"6ba622f63b6ec942f9f1a2f0eef4f363","prompt":"내 친구랑 셋이 밥을 먹다가 연인이 친구한테 새우를 까 줘요. 그걸 보면 어떤 반응이 나올 것 같아요?","samples":["“내 것도 하나 부탁해!” 하고 접시를 내밀어요.","그 자리에서는 웃지만 둘만 남으면 “나 아까 좀 질투 났어”라고 해요.","저는 별생각 없이 먹을 것 같아요. 평소에도 서로 음식 챙겨 주는 편이거든요."]},
      {"id":40064,"before":"5017767157f37eed2231e1ee0d4fafbb","prompt":"썸 타는 사람이 가족 생일 모임에 같이 가자고 해요. 가족들한테 나를 어떻게 소개해 주면 좋을까요?","samples":["그냥 제 이름만 알려 주면 편하게 밥 먹을 수 있을 것 같아요.","“요즘 마음이 가는 사람이야” 하고 솔직하게 소개해 주면 기분 좋을 것 같아요.","“아직 가족들 만나는 건 좀 일러. 다음에 인사드릴게” 하고 얘기하고 싶어요."]},
      {"id":40065,"before":"70eea70015a2fd91c20d5b9dee662f80","prompt":"데이트 중에 연인이 폰을 엎어 놓고도 알림이 올 때마다 확인해요. 언제쯤 한마디 하고 싶어질까요?","samples":["제가 중요한 얘기를 하다 두 번이나 멈추게 되면 말해요.","뭔가 급해 보이면 “먼저 답장하고 편하게 얘기할까?” 하고 물어요.","밥 먹는 동안만큼은 둘 다 폰을 치우자고 먼저 제안해요."]},
      {"id":40066,"before":"82f9462f7af2a07aee2707d499f80c11","prompt":"동창회에 갔더니 첫사랑이 바로 옆자리에 앉았어요. 집에 돌아와 연인에게 어디까지 얘기할 것 같아요?","samples":["옆에 앉았던 것까지 재밌는 동창회 얘기로 편하게 말해요.","지금 아무 감정도 없으면 굳이 첫사랑이었다는 말은 안 꺼내요.","마음이 조금이라도 흔들렸다면 정리한 뒤 그 얘기부터 하고 싶어요."]},
      {"id":40067,"before":"fef514a5e25186f8aaed78b03433ca02","prompt":"집에 와 보니 내 옷에서 좋아하는 사람의 향수 냄새가 나요. 다음에 만나면 뭐라고 하고 싶어요?","samples":["“네 향 나니까 집 가는 길에도 같이 있는 기분이더라.”","“무슨 향수 써?” 하고 관심만 슬쩍 보여요.","말로 하면 너무 티 날 것 같아서 혼자 웃고 말아요."]},
      {"id":40068,"before":"733d89048b535bcea0e92ff0cf180bdb","prompt":"사귀기 시작한 뒤 연인이 하루 일정을 전부 알려 달래요. 어느 정도까지 나누는 게 편한가요?","samples":["만날 시간과 늦게 귀가하는 날 정도면 충분해요.","그날 누구 만나고 뭘 하는지 소소한 얘기까지 주고받는 게 좋아요.","공유 캘린더엔 둘이 함께하는 약속만 넣고 싶어요."]},
      {"id":40069,"before":"b9ae02ead4bf41c86fafce6deea3ab60","prompt":"늘 내 이름을 부르던 연인이 단둘이 있을 때 처음으로 “자기야” 하고 불러요. 뭐라고 답하고 싶어요?","samples":["“한 번만 더 불러 봐.”","“난 네가 내 이름 부를 때가 더 설레.”","저도 아무렇지 않은 척 “응, 자기야?” 하고 받아쳐요."]},
      {"id":40070,"before":"7e6924edb6aab3ddee849eacc3a0a229","prompt":"누군가 내 연인에게 호감을 표현하는 문자를 보냈고 연인은 답장하지 않았어요. 이런 일은 어디까지 얘기해 주길 바라나요?","samples":["별일 아니어도 먼저 말해 주면 오히려 마음이 편해요.","답하지 않았다면 그런 연락까지 전부 보고할 필요는 없어요.","계속 연락해 오는 사람이라면 그때부터는 같이 얘기하고 싶어요."]},
      {"id":40071,"before":"86521fdf01df0dbbb8c222b4645a6083","prompt":"첫 데이트가 영 별로였는데 상대가 또 보자고 해요. 어떤 점이 마음에 남으면 한 번 더 만나고 싶을까요?","samples":["계획은 꼬여도 제 기분부터 챙겨 준 게 기억나서요.","둘 다 긴장해서 평소 모습이 아니었다는 느낌이 들어서요.","다시 보고 싶은 마음이 조금이라도 들어야 해요. 미안해서 약속을 잡고 싶진 않아요."]},
      {"id":40072,"before":"a79bbedcbcdb5bc2ca28c6d9b73bc352","prompt":"연인과 방이 두 개 있는 집에서 같이 산다면, 두 번째 방은 어떻게 쓰고 싶어요?","samples":["각자 푹 자고 싶은 날 쓸 수 있게 침실을 하나 더 두고 싶어요.","같이 자고 남는 방은 둘이 좋아하는 취미방으로 쓰고 싶어요.","둘 중 누가 됐든 혼자 있고 싶은 날 쓸 수 있게 비워 두고 싶어요."]},
      {"id":40073,"before":"f392e0538d965bfbadfb0dabe2a48682","prompt":"싸우다가 연인이 헤어지자고 했는데 다음 날 “진심은 아니었어”라고 해요. 다시 만날지 결정하려면 뭐가 필요할까요?","samples":["왜 그 말까지 나왔는지 숨김없이 듣고 싶어요.","또 싸우더라도 헤어지자는 말 대신 어떻게 쉬었다 얘기할지 같이 정하고 싶어요.","그 말을 들은 뒤엔 제 마음이 돌아오는지 시간을 두고 보고 싶어요."]}
    ]$reviewed$::jsonb) as copy(id integer, before text, prompt text, samples text[])
  loop
    select * into strict previous from pajang_private.personality_question_catalog where id = item.id;
    if (previous.prompt, previous.samples) = (item.prompt, item.samples) then
      continue;
    end if;
    if md5(jsonb_build_array(previous.prompt, previous.samples)::text) <> item.before
      or exists (select from pajang_private.answers where question_prompt = previous.prompt)
    then
      raise exception 'Pajang question % has changed or already has answers', item.id;
    end if;
    update pajang_private.personality_question_catalog
      set prompt = item.prompt, samples = item.samples where id = item.id;
  end loop;
end;
$copy_edit$;
